from pwn import *
import hexdump

def xor_bytes(b1, b2):
    return bytes([x ^ y for x, y in zip(b1, b2)])

def main():
    # Connect to the challenge server
    host = "crypto.chal.csaw.io"
    port = 4141
    r = remote(host, port)

    # Receive initial prompts
    r.recvuntil(b"Passwd\n")
    r.recvuntil(b">>")

    # Send fake password to collect ciphertexts
    r.sendline(b"fakepassword")

    # Receive the response including ciphertexts
    response = r.recvall(timeout=2).decode(errors="ignore")

    # Parse received data for C1 and C2
    ciphers = {}
    for line in response.split("\n"):
        if line.startswith("C1: "):
            ciphers["C1"] = line.split("C1: ")[1].strip()
        elif line.startswith("C2: "):
            ciphers["C2"] = line.split("C2: ")[1].strip()

    # Check if we have both ciphertexts
    if "C1" in ciphers and "C2" in ciphers:
        try:
            C1 = bytes.fromhex(ciphers["C1"])
            C2 = bytes.fromhex(ciphers["C2"])

            # XOR the ciphertexts
            result = xor_bytes(C1, C2)

            # Output the XOR result in hexdump format
            print("XOR Result:")
            print(hexdump.hexdump(result, result="return"))
        except ValueError as ve:
            print(f"Error converting ciphertexts to bytes: {ve}")
    else:
        print("Missing C1 or C2 in response. Debugging required.")

if __name__ == "__main__":
    main()

from pwn import *

# Connect to the challenge server
def collect_data():
    host = "crypto.chal.csaw.io"
    port = 4141

    sample_inputs = [
        "random_input123",
        "test123",
        "password",
        "FLAG{testflag}",
        "structured_example01",
        "structured_example99"
    ]

    collected_data = []

    for input_str in sample_inputs:
        try:
            with remote(host, port) as conn:
                conn.recvuntil(b"Passwd\n")
                conn.recvuntil(b">>")

                conn.sendline(input_str.encode())

                response = conn.recvall(timeout=2).decode()
                collected_data.append({
                    "input": input_str,
                    "response": response
                })
        except Exception as e:
            collected_data.append({
                "input": input_str,
                "error": str(e)
            })

    return collected_data


def save_collected_data(collected_data):
    with open("asr4cr_collected_data.txt", "w") as f:
        for entry in collected_data:
            f.write(f"Input: {entry['input']}\n")
            if "error" in entry:
                f.write(f"Error: {entry['error']}\n")
            else:
                f.write(f"Response: {entry['response']}\n")
            f.write("\n")


def main():
    collected_data = collect_data()
    save_collected_data(collected_data)


if __name__ == "__main__":
    main()
